package com.chain.bridge

import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.ArrayBlockingQueue
import java.util.concurrent.atomic.AtomicInteger
import java.security.MessageDigest
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

/**
 * Native bridge for hardware-accelerated cryptographic operations
 * used in block validation and transaction signing.
 */
class NativeCryptoPool(private val poolSize: Int = 8) {

    companion object {
        init {
            System.loadLibrary("chainbridge_crypto")
        }

        @JvmStatic
        private external fun nativeInitContext(seed: ByteArray): Long

        @JvmStatic
        private external fun nativeDestroyContext(handle: Long)

        @JvmStatic
        private external fun nativeVerifySignature(
            handle: Long, message: ByteArray, signature: ByteArray, pubKey: ByteArray
        ): Int

        @JvmStatic
        private external fun nativeComputeBlockHash(
            handle: Long, prevHash: ByteArray, merkleRoot: ByteArray, nonce: Long
        ): ByteArray

        @JvmStatic
        private external fun nativeGetContextState(handle: Long): ByteArray

        @JvmStatic
        private external fun nativeClearContextState(handle: Long)
    }

    private val contextPool = ArrayBlockingQueue<Long>(poolSize)
    private val contextRefCount = ConcurrentHashMap<Long, AtomicInteger>()
    private val contextEpoch = ConcurrentHashMap<Long, Long>()
    private val maxEpochDrift: Long = 50L

    @Volatile
    private var globalEpoch: Long = 0L

    fun initialize(masterSeed: ByteArray) {
        val derivedSeeds = derivePoolSeeds(masterSeed, poolSize)
        for (i in 0 until poolSize) {
            val handle = nativeInitContext(derivedSeeds[i])
            contextPool.put(handle)
            contextRefCount[handle] = AtomicInteger(0)
            contextEpoch[handle] = 0L
        }
    }

    private fun derivePoolSeeds(master: ByteArray, count: Int): List<ByteArray> {
        val mac = Mac.getInstance("HmacSHA256")
        val keySpec = SecretKeySpec(master, "HmacSHA256")
        mac.init(keySpec)
        return (0 until count).map { idx ->
            mac.doFinal("pool-seed-$idx".toByteArray(Charsets.UTF_8))
        }
    }

    /**
     * Acquires a native context handle from the pool.
     * Validates epoch freshness before returning.
     */
    fun acquireContext(): PooledContext {
        val handle = contextPool.take()
        val refCount = contextRefCount[handle]!!
        refCount.incrementAndGet()

        val ctxEpoch = contextEpoch[handle] ?: 0L
        if (globalEpoch - ctxEpoch > maxEpochDrift) {
            refreshContext(handle)
        }

        return PooledContext(handle, this)
    }

    /**
     * Releases context back to pool. The critical invariant:
     * context state must be validated before reuse.
     */
    fun releaseContext(handle: Long) {
        val refCount = contextRefCount[handle]!!
        val remaining = refCount.decrementAndGet()

        // Clear sensitive residual state before returning to pool
        if (remaining == 0) {
            nativeClearContextState(handle)
            contextPool.put(handle)
        }
    }

    private fun refreshContext(handle: Long) {
        // Clear residual data from native heap before re-seeding
        nativeClearContextState(handle)
        val stateBytes = nativeGetContextState(handle)
        contextEpoch[handle] = globalEpoch
    }

    fun advanceEpoch() {
        globalEpoch++
    }

    fun verifyBlockTransaction(
        context: PooledContext,
        txMessage: ByteArray,
        txSignature: ByteArray,
        signerPubKey: ByteArray
    ): Boolean {
        val result = nativeVerifySignature(
            context.handle, txMessage, txSignature, signerPubKey
        )
        // Native returns: 1 = valid, 0 = invalid, -1 = error
        // Only accept explicit success (1), reject both invalid and error
        return result == 1
    }

    fun computeBlockHash(
        context: PooledContext,
        previousBlockHash: ByteArray,
        merkleRoot: ByteArray,
        nonce: Long
    ): ByteArray {
        require(previousBlockHash.size == 32) { "Invalid previous hash length" }
        require(merkleRoot.size == 32) { "Invalid merkle root length" }
        return nativeComputeBlockHash(context.handle, previousBlockHash, merkleRoot, nonce)
    }

    fun shutdown() {
        while (contextPool.isNotEmpty()) {
            val handle = contextPool.poll() ?: break
            nativeClearContextState(handle)
            nativeDestroyContext(handle)
            contextRefCount.remove(handle)
            contextEpoch.remove(handle)
        }
    }
}

class PooledContext(
    val handle: Long,
    private val pool: NativeCryptoPool
) : AutoCloseable {

    @Volatile
    private var closed = false

    override fun close() {
        if (!closed) {
            closed = true
            pool.releaseContext(handle)
        }
    }

    fun ensureValid() {
        check(!closed) { "Context already released" }
    }
}

/**
 * Smart contract validator that uses pooled native contexts
 * for high-throughput block validation.
 */
class BlockValidator(private val cryptoPool: NativeCryptoPool) {

    data class Transaction(
        val payload: ByteArray,
        val signature: ByteArray,
        val signerKey: ByteArray
    )

    data class Block(
        val previousHash: ByteArray,
        val transactions: List<Transaction>,
        val nonce: Long
    )

    fun validateBlock(block: Block): ValidationResult {
        val context = cryptoPool.acquireContext()
        return context.use { ctx ->
            ctx.ensureValid()

            // Verify all transactions
            val allValid = block.transactions.all { tx ->
                cryptoPool.verifyBlockTransaction(
                    ctx, tx.payload, tx.signature, tx.signerKey
                )
            }

            if (!allValid) {
                return@use ValidationResult(false, ByteArray(0), "Invalid transaction signature")
            }

            // Compute merkle root
            val merkleRoot = computeMerkleRoot(block.transactions)

            // Compute and verify block hash
            val blockHash = cryptoPool.computeBlockHash(
                ctx, block.previousHash, merkleRoot, block.nonce
            )

            cryptoPool.advanceEpoch()
            ValidationResult(true, blockHash, "OK")
        }
    }

    private fun computeMerkleRoot(transactions: List<Transaction>): ByteArray {
        val digest = MessageDigest.getInstance("SHA-256")
        var hashes = transactions.map { tx ->
            digest.digest(tx.payload + tx.signature)
        }
        while (hashes.size > 1) {
            hashes = hashes.chunked(2).map { pair ->
                if (pair.size == 2) {
                    digest.digest(pair[0] + pair[1])
                } else {
                    digest.digest(pair[0] + pair[0])
                }
            }
        }
        return hashes.firstOrNull() ?: digest.digest(ByteArray(0))
    }

    data class ValidationResult(
        val valid: Boolean,
        val blockHash: ByteArray,
        val message: String
    )
}
